-- Preserve the bilingual server rules that previously lived in TypeScript.
INSERT INTO `managed_sections` (`id`, `version`, `created_at`, `updated_at`)
VALUES ('rules', 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));

INSERT INTO `managed_section_translations` (
  `managed_section_id`, `locale`, `content`, `created_at`, `updated_at`
) VALUES
(
  'rules',
  'ja',
  CAST('{"id":"rules","eyebrow":"Rules","title":"重要なルール","description":"参加者が安心して遊べるよう、特に重要な項目を簡潔にご案内します。サーバールールの全文もこのWebサイトで確認できます。","noticeTitle":"参加前に必ず確認してください","notice":"時間外レイド、チーミング、不正行為、他者への不適切な言動には、違反内容に応じて各ルールに定める警告・キック・有期BAN・永久BANを適用します。判断に迷う場合や誤操作があった場合は、速やかにDiscordのチケットから運営へご連絡ください。","items":[{"id":"raid-window","title":"レイド可能時間","description":"平日18:00〜24:00、土・日12:00〜24:00のみレイド可能です。時間外に他プレイヤーの建築物へ攻撃した場合は段階的に処分し、実際に破壊した場合は次回ワイプまで自動BANします。対象外となる行為はルール全文をご確認ください。","icon":"clock","status":"confirmed","important":true},{"id":"team-size","title":"チーム人数上限","description":"チームは最大4人です。チーム外プレイヤーとの物資共有、共闘、拠点共有は禁止し、違反は警告から永久BANの対象となります。引退時に物資を譲渡した場合は寝袋・TCなどの権限を解除し、速やかにログアウトして当該ワイプ中のプレイを控えてください。","icon":"users","status":"confirmed","important":true},{"id":"fair-play","title":"不正行為への対応","description":"チート、グリッチ、不正ツールなど、公式サーバーで禁止されている行為は永久BAN対象です。異議申し立てはDiscordの#claim-ticketで受け付け、Admin / ModeratorへのDMでは対応しません。","icon":"shield","status":"confirmed"},{"id":"community-conduct","title":"コミュニティでの振る舞い","description":"暴言、政治的・差別的な不適切発言、過度な煽り、誹謗中傷や執拗な個人攻撃は禁止です。チャット、VC、建築物、看板、自販機、拠点、Discordも対象で、問題のある設置物等は撤去します。違反は警告から永久BANの対象となり、悪質な場合は事前警告なく処罰します。","icon":"message","status":"confirmed"},{"id":"reporting","title":"違反の報告方法","description":"チートなどが疑われる場合はRust内のF7レポートを利用し、録画などの証拠は必要に応じてDiscordのチケットへお送りください。その他の違反報告もチケットで受け付けます。時間外に誤って建築物を破壊した場合も、速やかに報告してください。","icon":"report","status":"confirmed"},{"id":"rule-updates","title":"ルールの更新","description":"運営は可能な限り公平に対応し、健全な環境を保つためルールを予告なく変更する場合があります。有志での運営のため、完全な環境や即時対応を保証するものではありません。","icon":"refresh","status":"confirmed"}],"rulebook":{"title":"Japan Hideaway Server サーバールール","openLabel":"サーバールール全文を見る","closeLabel":"サーバールール全文を閉じる","blocks":[{"id":"raid-rules","title":"レイド可能時間と時間外レイド","paragraphs":["「時間外レイド」とは、レイド可能時間外に他プレイヤーの建築物を攻撃または破壊する行為です。時刻はすべて日本時間（JST）です。"],"items":[{"id":"weekdays","label":"平日のレイド可能時間","description":"18:00〜24:00"},{"id":"weekends","label":"土曜日・日曜日のレイド可能時間","description":"12:00〜24:00"},{"id":"prohibited-scope","label":"時間外レイドの対象","description":"他プレイヤーの建築物（壁・ドア・ボート建築など）への攻撃・破壊"},{"id":"exemptions","label":"時間外レイドの対象外","description":"野外設置物（ターレットなど）の破壊、パスコードレイド、藁・木強化建築、自拠点および周辺TC柱の破壊"},{"id":"attack-enforcement","label":"建築物を破壊していない違反","description":"1回目は警告、2回目はサーバーキック、キック後に再度違反した場合は違反者とチーム全員を次回ワイプまでBAN"},{"id":"destruction-enforcement","label":"建築物を破壊した場合","description":"違反回数にかかわらず、自動的に次回ワイプまでBAN。ログ確認後、違反者の拠点を破壊します"},{"id":"accident","label":"誤って破壊した場合","description":"速やかに運営へ報告してください"}]},{"id":"cheating","title":"1. チート・グリッチ・不正ツールの使用","penalty":"永久BAN","paragraphs":["公式サーバーで禁止されている行為全般を禁止します。検知や調査の状況により、自動的または一時的にサーバーからキック・BANする場合があります。"],"items":[{"id":"party-member","label":"同一パーティでプレイしていた場合","description":"初回は30日BAN、2回目以降は永久BAN"},{"id":"appeal","label":"異議申し立て","description":"Admin / Moderator への DM 直接対応は行いません。Discord の #claim-ticket にて対応いたします。"}]},{"id":"conduct","title":"2. 暴言・差別発言・過度な煽り・誹謗中傷","penalty":"警告〜永久BAN","paragraphs":["政治的・差別的な発言、執拗な個人攻撃など、社会通念上許容される範囲を超えた不適切な言動を禁止します。"],"items":[{"id":"locations","description":"ゲーム内チャット、VC、自動販売機、建築物、看板、拠点およびDiscordサーバー内のチャンネルが対象です。"},{"id":"removal","description":"問題のある建築物、看板、自動販売機、拠点などは撤去します。"},{"id":"serious","description":"悪質性が高い場合は、事前警告なく有期BANまたは永久BANとすることがあります。"}]},{"id":"teaming","title":"3. チーム人数制限違反（チーミング）","penalty":"警告〜永久BAN","paragraphs":["チーム人数は最大4人です。チーム外プレイヤーとの物資共有、共闘、拠点共有を禁止します。"],"items":[{"id":"retirement","label":"引退時の物資譲渡","description":"譲渡自体は容認しますが、譲渡後は寝袋・TCなどの権限を解除し、速やかにログアウトして当該ワイプ中のプレイを控えてください。"}]},{"id":"feedback","title":"サーバーへの意見・批判について","paragraphs":["サーバーや運営に関する意見や批判そのものは禁止していません。","ただし、意見や批判を理由として、暴言、差別、誹謗中傷、執拗な個人攻撃など、社会通念上許容される範囲を超えた不適切な行為を行うことは禁止します。"]},{"id":"operations","title":"運営方針・報告方法","paragraphs":["基本的にプレイスタイルは制限しませんが、本ルールで禁止する不適切な行為はプレイスタイルとは認めません。警告を無視する場合や悪質なケースはBAN処置の対象です。"],"items":[{"id":"fairness","description":"運営は、すべてのプレイヤーに対して可能な限り公平に対応します。"},{"id":"cheat-report","description":"チート、グリッチ、不正ツールの使用が疑われる場合はRust内のF7レポートを利用し、録画などの証拠は必要に応じてDiscordのチケットから運営へ報告してください。"},{"id":"other-report","description":"その他のルール違反もDiscordのチケット機能から報告してください。"},{"id":"changes","description":"健全な運営のため、ルールは予告なく変更される場合があります。"},{"id":"volunteer","description":"運営は有志のボランティアとして時間や費用を負担しながら管理しています。サーバー環境やチーター対応は可能な限り改善しますが、常に完全な環境や即時対応を保証するものではありません。"},{"id":"choice","description":"サーバーの方針や環境が合わない場合は、他のサーバーの利用もご検討ください。"}] }],"supplementaryNote":"このWebサイトに掲載する内容を最新のサーバールールとして扱います。利用規約と最新のお知らせもあわせてご確認ください。","lastUpdatedLabel":"最終更新日","lastUpdated":"2026年8月25日"}}' AS JSON),
  CURRENT_TIMESTAMP(3),
  CURRENT_TIMESTAMP(3)
),
(
  'rules',
  'en',
  CAST('{"id":"rules","eyebrow":"Rules","title":"Important Rules","description":"This page provides a concise overview of the most important rules for a safe experience. The complete Server Rules are also available on this website.","noticeTitle":"Read before joining","notice":"Raiding outside the permitted hours, teaming, unfair play, and abusive conduct are handled according to the specific rule, with penalties including warnings, kicks, temporary bans, and permanent bans. If you are unsure about an action or make an accidental mistake, contact staff promptly through a Discord ticket.","items":[{"id":"raid-window","title":"Raiding Hours","description":"Raiding is allowed from 18:00 to 24:00 on weekdays and 12:00 to 24:00 on Saturday and Sunday. Attacking another player''s building outside these hours is handled through escalating penalties; actually destroying it results in an automatic ban until the next wipe. See the complete Rules for exemptions.","icon":"clock","status":"confirmed","important":true},{"id":"team-size","title":"Team Size Limit","description":"Teams are limited to four players. Sharing supplies, fighting together, or sharing a base with players outside your team is prohibited and may result in penalties ranging from a warning to a permanent ban. If you transfer supplies when retiring, clear sleeping bag and TC authorization, log out promptly, and do not play again during that wipe.","icon":"users","status":"confirmed","important":true},{"id":"fair-play","title":"Unfair Play and Exploits","description":"Cheats, glitches, unauthorized tools, and other conduct prohibited on official servers are subject to a permanent ban. Appeals are handled through Discord #claim-ticket; Admins and Moderators do not respond to direct messages.","icon":"shield","status":"confirmed"},{"id":"community-conduct","title":"Community Conduct","description":"Abuse, inappropriate political or discriminatory statements, excessive taunting, defamation, and persistent personal attacks are prohibited. This applies to chat, voice, buildings, signs, vending machines, bases, and Discord, and problematic structures or objects will be removed. Penalties range from a warning to a permanent ban, and serious cases may be penalized without prior warning.","icon":"message","status":"confirmed"},{"id":"reporting","title":"Reporting Violations","description":"Use Rust''s F7 report for suspected cheating, and send recordings through a Discord ticket when needed. Other rule violations are also handled through tickets. If you accidentally destroy a building outside raiding hours, report it promptly.","icon":"report","status":"confirmed"},{"id":"rule-updates","title":"Rule Updates","description":"Staff will act as fairly as possible and may change rules without prior notice to maintain a healthy environment. The server is run by community volunteers, so a perfect environment and immediate response cannot be guaranteed.","icon":"refresh","status":"confirmed"}],"rulebook":{"title":"Japan Hideaway Server Rules","openLabel":"View the Complete Server Rules","closeLabel":"Close the Complete Server Rules","blocks":[{"id":"raid-rules","title":"Permitted Raid Hours and Off-Hours Raiding","paragraphs":["“Off-hours raiding” means attacking or destroying another player''s building outside the permitted raid hours. All times are in Japan Standard Time (JST)."],"items":[{"id":"weekdays","label":"Permitted raid hours on weekdays","description":"18:00–24:00"},{"id":"weekends","label":"Permitted raid hours on Saturday and Sunday","description":"12:00–24:00"},{"id":"prohibited-scope","label":"What counts as off-hours raiding","description":"Attacking or destroying another player''s building, including walls, doors, and boat bases"},{"id":"exemptions","label":"What does not count as off-hours raiding","description":"Destroying outdoor deployables such as turrets, code raids, twig or wood-upgrade structures, your own base, and nearby TC pillars"},{"id":"attack-enforcement","label":"Violation without destroying a building","description":"First violation: warning; second violation: server kick; another violation after a kick: the offender and the entire team are banned until the next wipe"},{"id":"destruction-enforcement","label":"If a building is destroyed","description":"Regardless of prior violations, the player is automatically banned until the next wipe. Staff will destroy the offender''s base after reviewing the logs"},{"id":"accident","label":"Accidental destruction","description":"Report it to staff immediately"}]},{"id":"cheating","title":"1. Cheats, Glitches, and Unauthorized Tools","penalty":"Permanent ban","paragraphs":["All conduct prohibited on official servers is also prohibited here. Depending on automated detection and the investigation, a player may be automatically or temporarily kicked or banned from the Server."],"items":[{"id":"party-member","label":"Players in the same party","description":"A 30-day ban for the first incident and a permanent ban for the second and later incidents"},{"id":"appeal","label":"Appeals","description":"Admins and Moderators do not respond to direct messages. Use Discord #claim-ticket for assistance."}]},{"id":"conduct","title":"2. Abuse, Discriminatory Language, Excessive Taunting, and Defamation","penalty":"Warning to permanent ban","paragraphs":["Political or discriminatory statements, persistent personal attacks, and other conduct beyond generally acceptable social standards are prohibited."],"items":[{"id":"locations","description":"This applies to in-game chat, voice chat, vending machines, buildings, signs, bases, and channels in the Discord server."},{"id":"removal","description":"Problematic buildings, signs, vending machines, bases, and similar content will be removed."},{"id":"serious","description":"Serious conduct may result in a temporary or permanent ban without prior warning."}]},{"id":"teaming","title":"3. Team-Size Violations (Teaming)","penalty":"Warning to permanent ban","paragraphs":["Teams are limited to four players. Sharing supplies, fighting together, or sharing a base with players outside your team is prohibited."],"items":[{"id":"retirement","label":"Transferring supplies when retiring","description":"The transfer itself is allowed, but afterward you must clear sleeping bag, TC, and other authorization, log out promptly, and refrain from playing again during that wipe."}]},{"id":"feedback","title":"Feedback and Criticism","paragraphs":["Feedback or criticism regarding the Server or its operators is not itself prohibited.","However, feedback or criticism does not justify abuse, discrimination, defamation, persistent personal attacks, or other conduct beyond generally acceptable social standards."]},{"id":"operations","title":"Operating Policy and Reports","paragraphs":["Playstyles are generally not restricted, but prohibited conduct under these Rules is not recognized as a playstyle. Ignoring warnings or engaging in serious misconduct may result in a ban."],"items":[{"id":"fairness","description":"The operators will treat all players as fairly as reasonably possible."},{"id":"cheat-report","description":"If you suspect cheats, glitches, or unauthorized tools, use Rust''s F7 report feature and, when appropriate, provide recordings or other evidence through a Discord ticket."},{"id":"other-report","description":"Report other rule violations through the Discord ticket system."},{"id":"changes","description":"These Rules may be changed without prior notice to maintain a healthy Server environment."},{"id":"volunteer","description":"The Server is managed by volunteers who contribute their own time and money. We will improve the Server environment and anti-cheat response where reasonably possible, but cannot guarantee a perfect environment or an immediate response at all times."},{"id":"choice","description":"If the Server''s policies or environment do not suit you, please consider using another server."}]}],"supplementaryNote":"The content on this website is the current authoritative version of the Server Rules. Please also review the Terms of Service and latest announcements.","lastUpdatedLabel":"Last updated","lastUpdated":"August 25, 2026"}}' AS JSON),
  CURRENT_TIMESTAMP(3),
  CURRENT_TIMESTAMP(3)
);
